insert into email_templates (name, subject, body_html, variables, is_active) values
('business-pending-admin', 'Nuevo negocio por verificar — {{businessName}}', '<div style="font-family:sans-serif;color:#12241a;line-height:1.6;max-width:600px"><h2 style="margin:0 0 12px;color:#BF1C19">Nuevo negocio registrado</h2><p>Un nuevo negocio se registró y está pendiente de verificación:</p><ul style="padding-left:20px"><li><b>Negocio:</b> {{businessName}} ({{businessType}})</li><li><b>Email:</b> {{ownerEmail}}</li><li><b>Teléfono:</b> {{phone}}</li><li><b>Descripción:</b> {{description}}</li></ul><p><a href="{{adminUrl}}" style="display:inline-block;background:#BF1C19;color:#fff;padding:10px 18px;border-radius:999px;text-decoration:none;font-weight:600">Ver en admin</a></p><p style="color:#6b6b6b;font-size:13px;margin-top:16px">Acción requerida: aproba o rechaza desde el panel de administración. El negocio está en estado <b>pendiente</b> y no es visible hasta ser aprobado.</p></div>', '["businessName","businessType","ownerEmail","phone","description","adminUrl"]'::jsonb, true),
('business-pending-owner', 'Recibimos tu solicitud — {{businessName}} en revisión', '<div style="font-family:sans-serif;color:#12241a;line-height:1.6;max-width:600px"><h2 style="margin:0 0 12px;color:#BF1C19">¡Gracias por registrarte, {{businessName}}!</h2><p>Recibimos tu solicitud para unirte a Rolé. Nuestro equipo la revisará y te contactará en <b>menos de 24 horas</b> para activarlo.</p><p>Mientras tanto, no necesitas hacer nada más. Te avisaremos por este correo cuando tu negocio sea aprobado.</p><p style="color:#6b6b6b;font-size:13px">Si tienes dudas, responde a este correo o escribe a negocios@role.app</p></div>', '["businessName"]'::jsonb, true),
('business-approved', '¡Tu negocio {{businessName}} ya está activo en Rolé!', '<div style="font-family:sans-serif;color:#12241a;line-height:1.6;max-width:600px"><h2 style="margin:0 0 12px;color:#1A7A3A">¡Aprobado!</h2><p>Tu negocio <b>{{businessName}}</b> ya está activo y visible para miles de usuarios cerca de ti.</p><p>Ya puedes publicar tu primera oferta y empezar a recuperar valor de tu excedente.</p><p><a href="{{appUrl}}" style="display:inline-block;background:#BF1C19;color:#fff;padding:10px 18px;border-radius:999px;text-decoration:none;font-weight:600">Publicar mi primera oferta</a></p></div>', '["businessName","appUrl"]'::jsonb, true),
('business-rejected', 'Actualización sobre tu solicitud — {{businessName}}', '<div style="font-family:sans-serif;color:#12241a;line-height:1.6;max-width:600px"><h2 style="margin:0 0 12px;color:#8b3a2a">Revisión de tu solicitud</h2><p>Hemos revisado tu solicitud para <b>{{businessName}}</b> y por el momento no podemos aprobarla.</p><p><b>Motivo:</b> {{rejectionReason}}</p><p>Si crees que es un error o quieres corregirlo, responde a este correo y te ayudamos.</p><p style="color:#6b6b6b;font-size:13px">Equipo Rolé — negocios@role.app</p></div>', '["businessName","rejectionReason"]'::jsonb, true)
